#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include "student.h"
#include "bubble.h"

int main()
{
    // Open the grades file for reading
    std::ifstream infile("grades");
    if (!infile) {
        std::cerr << "Could not open the file." << std::endl;
        return 1;
    }

    // Skip the first line (CSCE1040)
    std::string line;
    std::getline(infile, line);

    // Vector to store student pointers
    std::vector<student*> student_ptrs;

    // Read and initialize each student
    std::string first, last;
    int exam1, exam2, exam3;
    while (infile >> first >> last >> exam1 >> exam2 >> exam3) {
        student* s = new student();
        s->first = new std::string(first);
        s->last = new std::string(last);
        s->exam1 = exam1;
        s->exam2 = exam2;
        s->exam3 = exam3;
        s->mean = (exam1 + exam2 + exam3) / 3.0;
        student_ptrs.push_back(s);
    }

    // Close the file
    infile.close();

    // Sort the students by mean score
    bubble(student_ptrs.data(), student_ptrs.size());

    // Display the sorted students
    for (student* s : student_ptrs) {
        std::cout << *s->first << " " << *s->last << " " << s->mean << std::endl;
        delete s->first;
        delete s->last;
        delete s;
    }

    // Clear the vector (not strictly necessary, but good practice)
    student_ptrs.clear();

    return 0;
}
